'use client';
import React from 'react';
export type AnvisaAlerta = 'AÇÚCAR ADICIONADO' | 'GORDURA SATURADA' | 'SÓDIO';
export interface TemplateProps { nutrients: AnvisaAlerta[]; }


const AltoEmTSpan = ({ config }: { config: any }) => (
  <tspan
    style={{ 
      fontVariant: 'normal', 
      fontWeight: 700, 
      fontStretch: 'condensed', 
      fontSize: '19.0895px', 
      fontFamily: 'Arial', 
      fill: '#231f20' 
    }}
    {...config}
  >
    ALTO EM
  </tspan>
);

const NutrientTSpan = ({ nutrient, configs }: { nutrient: AnvisaAlerta; configs: any[] }) => {
  const commonStyle = { 
    fontVariant: 'normal', 
    fontWeight: 700, 
    fontStretch: 'condensed', 
    fontSize: '19.0895px', 
    fontFamily: 'Arial', 
    fill: '#ffffff',
    textAnchor: 'middle' as const,
    dominantBaseline: 'central' as const
  };
  
  if (nutrient === 'AÇÚCAR ADICIONADO') {
    return (
      <>
        <tspan style={commonStyle} {...configs[0]}>AÇÚCAR </tspan>
        {configs.length > 1 && <tspan style={commonStyle} {...configs[1]}>ADICIONADO</tspan>}
      </>
    );
  }
  if (nutrient === 'GORDURA SATURADA') {
    return (
      <>
        <tspan style={commonStyle} {...configs[0]}>GORDURA </tspan>
        {configs.length > 1 && <tspan style={commonStyle} {...configs[1]}>SATURADA</tspan>}
      </>
    );
  }
  return (
    <tspan style={commonStyle} {...configs[0]}>SÓDIO</tspan>
  );
};

